function caseKind(){return current==='incident'?'recovery':current==='economics'?'cost':current}
const paths={home:'<path d="m3 10 9-7 9 7v10H4V10m5 10v-7h6v7"/>',spark:'<path d="m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7L12 3Z"/><path d="m20 2 .6 1.4L22 4l-1.4.6L20 6l-.6-1.4L18 4l1.4-.6L20 2Z"/>',chart:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',back:'<path d="M20 12H5m6-6-6 6 6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v5c0 5-8 10-8 10S4 16 4 11V6l8-3Z"/><path d="m8 11 3 3 5-5"/>',link:'<path d="m9 15 6-6M8 8l3-3a4 4 0 0 1 6 6l-2 2M9 11l-2 2a4 4 0 0 0 6 6l3-3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="white"/><circle cx="16" cy="17" r="3" fill="white"/>',gift:'<path d="M3 8h18v5H3zM5 13v8h14v-8M12 8v13M12 8C3 8 6-1 12 8c6-9 9 0 0 0Z"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 8h18m-6 5h6v4h-6z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',pause:'<path d="M8 5v14M16 5v14"/>',play:'<path d="m8 4 12 8-12 8V4Z"/>',doc:'<path d="M5 3h10l4 4v14H5V3Zm9 0v5h5M8 12h8m-8 4h6"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',bolt:'<path d="m13 2-9 12h7l-1 8L21 9h-8l0-7Z"/>'};
const $=id=>document.getElementById(id),safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<span class="ico" aria-hidden="true"><svg viewBox="0 0 24 24">${paths[name]||paths.spark}</svg></span>`;
const pill=(s,c='')=>`<span class="pill ${c}">${s}</span>`;
const btn=(s,action,c='')=>`<button class="btn ${c}" onclick="${action}">${s}</button>`;
const CASES={
clarity:{title:'The cashback promise meets a card restriction',short:'Offer clarity',tag:'Conversion growth',color:'amber',channel:'Engage offer → campaign landing card',campaign:'Festive Edit',intro:'Ananya, 180 shoppers tried your cashback offer with an ineligible payment method. Could clearer terms earlier in the journey help?',story:'Ananya runs Sunday Home, a growing homeware brand. Her Festive Edit campaign promises ₹500 cashback. Customers discover the credit-card condition late, just before paying.',pain:'“People are interested. Why do they leave as soon as they try the offer?”',signal:'180 eligibility rejections',impact:'126 had no paid order in 24h',metric:'Paid conversion & contribution',question:'Where can we make the offer clearer?',why:'I can prepare the right action once I know which surface you control.',choices:[['owned','Our campaign landing card','Prepare an approved card update'],['handoff','My agency owns that page','Prepare a brief for my agency']],finding:'The card restriction is absent from the headline. The footer includes it. Moving the same conditions upfront is worth testing; the data does not prove why each shopper left.',steps:[['Evidence agent','Join campaign visits and orders','1,200 of 1,250 checkout sessions matched.'],['Offer analyst','Compare wording with offer terms','Cedar credit card eligibility appears only in the footer.'],['Experiment planner','Prepare a clarity test','Keep the benefit unchanged; test earlier disclosure.']],base:'Get ₹500 cashback with an eligible Cedar Bank credit card on orders of ₹2,500 or more. Cashback is credited by the bank within 90 days.',action:'Test a clearer offer card',scope:'Campaign landing card · 50/50 visitor split',cap:1000,max:2000,capLabel:'Maximum visitors',budget:0,source:'Campaign variant + visit ID → checkout → order → payment/refund. Offer-validation events require explicit instrumentation.',evidence:[['Matched checkouts','1,200 / 1,250'],['Offer attempts','600'],['Eligibility rejections','180'],['Later paid within 24h','54 of 180'],['No matched purchase in 24h','126 of 180']],original:'Get ₹500 cashback. Bring the festive feeling home.',terms:'Cedar Bank credit cards · ₹2,500 minimum · Bank credits within 90 days. Fictional partner.',outcome:['Paid conversion','30.0%','33.0%','+3 percentage points'],benefit:'Potentially more paid orders without adding incentive cost.',model:'An LLM compares campaign wording with retrieved, versioned offer conditions. Deterministic eligibility checks and a randomised test validate the recommendation.',guard:'Keep the bank offer unchanged. Only the approved card text can change. Pause if offer terms expire or campaign-to-order mapping fails.'},
recovery:{title:'An interested shopper meets a payment outage',short:'Payment recovery',tag:'Revenue recovery',color:'blue',channel:'Razorpay payments → consented SMS',campaign:'Weekend collection',intro:'Ananya, a payment incident affected 84 campaign shoppers. The sample health check shows the route has recovered. I can check who still needs help paying.',story:'During Sunday Home’s weekend promotion, a temporary payment issue interrupts checkouts. The store owner is tempted to send every failed customer a discount, but some have already paid.',pain:'“Who still needs a retry link—and who should I leave alone?”',signal:'84 shoppers affected',impact:'52 still unpaid after deduplication',metric:'Incremental paid orders after retry',question:'How should we help the remaining shoppers?',why:'I found 38 with a recorded marketing opt-in and 14 without one. Contact permission changes what I can do.',choices:[['sms','Contact the 38 opted-in shoppers','One SMS, only if still unpaid'],['handoff','Prepare an internal follow-up list','No customer messages']],finding:'32 of the 84 shoppers subsequently paid. Of the 52 remaining, only 38 have the required recorded consent in this example. A last-moment paid-status check is essential.',steps:[['Payment analyst','Check the incident and current health','Payment health has recovered in the sample window.'],['Recovery agent','Remove successful and duplicate orders','52 remain unpaid; 38 have recorded opt-in.'],['Policy checker','Prepare a bounded retry','One contact per shopper; no additional discount.']],base:'Your Sunday Home checkout is ready to try again. If you still want your items, use your secure order link. Ignore this if you have already paid. Opt out of reminders anytime.',action:'Offer one safe payment retry',scope:'50% consented SMS / 50% no-message holdout · Paid-status recheck',cap:38,max:38,capLabel:'Maximum eligible customers',budget:0,source:'Campaign-linked order ID → attempt status → incident health → later payment → consent ledger. Link reuse/creation needs a supported order integration.',evidence:[['Affected unique shoppers','84'],['Subsequently paid','32'],['Still unpaid','52'],['Recorded opt-in','38'],['No marketing opt-in','14 · Excluded']],original:'Send another discount to everyone whose payment failed.',terms:'One message per customer. No new incentive. No stored card credentials. Only supported secure payment links.',outcome:['Paid orders per eligible shopper','10.5%','26.3%','Early recovery signal'],benefit:'Recover genuine demand while avoiding repeat messages and unnecessary discounts.',model:'Rules determine paid status, consent and retry eligibility. AI interprets mixed incident evidence and drafts a context-aware explanation. ML timing models are optional, not necessary for the first version.',guard:'Pause if payment health deteriorates. Recheck payment before sending. Deduplicate by order/customer. Never infer consent from having a phone number.'},
cost:{title:'More redemptions, less contribution',short:'Incentive efficiency',tag:'Profitable growth',color:'purple',channel:'Engage loyalty → controlled reward campaign',campaign:'Welcome back rewards',intro:'Ananya, your ₹150 return-customer reward is being redeemed more often, but contribution per order is down. I can check whether a smaller reward deserves a limited test.',story:'Sunday Home offers a ₹150 merchant-funded reward to returning shoppers. Orders rise, but Ananya’s cost sheet shows ₹500 contribution before the reward and only ₹350 after it.',pain:'“Are these discounts bringing extra orders, or paying customers who would buy anyway?”',signal:'₹150 merchant-funded reward',impact:'₹350 contribution after reward',metric:'Contribution per assigned customer',question:'What contribution floor should the new reward variant protect?',why:'I need your business limit. Payment data alone does not tell me how much margin you need.',choices:[['350','At least ₹350 per retained order','Keep today’s floor'],['400','At least ₹400 per retained order','Protect a higher margin']],finding:'The sample cost sheet shows ₹500 per retained order before incentive cost. A ₹75 reward would leave ₹425. This is not evidence that customers will respond equally; a control group is needed.',steps:[['Cost analyst','Reconcile who funds each reward','Merchant funding and costs are verified in sample records.'],['Incentive analyst','Check the contribution constraint','₹500 before reward; ₹350 after current ₹150 reward.'],['Experiment planner','Prepare a smaller-reward comparison','Test a separate ₹75 reward against the existing ₹150 reward.']],base:'A little thank-you for coming back: ₹75 off your next eligible Sunday Home purchase. See the reward terms before you pay.',action:'Test a separate ₹75 reward variant',scope:'Existing ₹150 reward vs. new ₹75 reward · 50/50 customers',cap:200,max:400,capLabel:'Maximum customers',budget:22500,source:'Assigned campaign variant → paid order → reward redemption → merchant/bank funding ledger → variable costs and refunds.',evidence:[['Contribution before reward','₹500 per retained order'],['Current merchant reward','₹150'],['Contribution after current reward','₹350'],['Proposed reward variant','₹75'],['Contribution after proposed reward','₹425 before incremental delivery costs']],original:'₹150 off your next eligible Sunday Home purchase.',terms:'A separate campaign variant is created. Existing issued rewards and live offer conditions are honoured.',outcome:['Contribution per assigned customer','₹70','₹76.50','+₹6.50 per customer'],benefit:'Find whether lower incentive cost can improve contribution despite a possible conversion trade-off.',model:'Causal experiments estimate incremental contribution. Uplift or causal-forest models become candidates after enough randomised tests. An LLM explains trade-offs, but deterministic cost calculations enforce the budget.',guard:'Do not reduce already-issued rewards. Confirm funding and cost data. Create a new offer when required; do not edit an immutable live offer. Budget uses maximum possible redemptions.'},
repeat:{title:'The next purchase needs a better moment',short:'Repeat-purchase timing',tag:'Retention growth',color:'green',channel:'BillMe retention → consented email',campaign:'Come back to Sunday',intro:'Ananya, repeat purchases tend to happen around 45–60 days after the last order. Your current reminder goes to everyone at the same time. Want to explore a more relevant window?',story:'Sunday Home sells table linen, candles and home accessories. Ananya runs a blanket monthly email, but different customers are at very different points since their last purchase.',pain:'“Who should hear from us now, without pestering people who just bought?”',signal:'45–60 day repeat window',impact:'Recent buyers still enter the broad campaign',metric:'Incremental repeat contribution',question:'Which group should we try first?',why:'A narrower recency window gives you control over who hears from the brand.',choices:[['45','45+ days since last purchase','Up to 800 opted-in customers'],['60','60+ days since last purchase','Up to 600 opted-in customers']],finding:'Recency is a useful starting signal, not proof that a customer wants to buy. A no-message holdout helps separate natural repeat purchases from the campaign’s effect.',steps:[['Cohort analyst','Check purchase and refund history','Recent purchases and fully refunded orders are handled separately.'],['Audience agent','Check channel consent and recency','800 opted-in buyers at 45+ days; 600 at 60+ days.'],['Experiment planner','Prepare a reminder and holdout','One email, no extra discount, customer-level assignment.']],base:'Make room for your next Sunday. Explore new pieces for the home, chosen for slow mornings and everyday moments. Unsubscribe anytime.',action:'Try a purchase-timed reminder',scope:'50% email / 50% no-message holdout · Existing opt-in only',cap:600,max:800,capLabel:'Maximum assigned customers',budget:0,source:'Merchant-scoped customer ID → last retained purchase → consent and contact history → assigned group → payment/refund. Consent and identity require merchant CRM data.',evidence:[['Opted-in buyers at 45+ days','800'],['Subset at 60+ days','600'],['Recent buyers','Excluded before dispatch'],['Extra discount','None'],['Control group','No-message holdout']],original:'Send the same monthly email to every past buyer.',terms:'Exclude opt-outs and anyone who buys again before dispatch. Honour frequency caps. No cross-merchant profiling.',outcome:['Repeat purchase rate','4.0%','6.0%','+2 percentage points'],benefit:'Increase repeat purchases with fewer irrelevant contacts and no added discount.',model:'Start with recency rules plus a randomised holdout. Survival analysis or calibrated gradient-boosted propensity models can improve timing with enough history. An LLM drafts the message and explains the audience.',guard:'Recheck recency and consent at dispatch. One campaign contact in 14 days. Pause on elevated complaints or broken attribution; do not silently expand the audience.'}}
let current='clarity',tab='overview',page='overview',raf=0,lastTick=0;const sessions={};
function session(id=current){return sessions[id]||(sessions[id]={stage:'intro',messages:[],choice:null,cap:CASES[id].cap,copy:CASES[id].base,run:null,logs:[],approved:false,paused:false,results:false,connected:true,draftInput:''})}
const C=()=>CASES[current],A=()=>session();
function log(t,id=current){session(id).logs.push({t:new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}),text:t})}
function bot(t,id=current){session(id).messages.push({role:'bot',text:t})}
function user(t){A().messages.push({role:'user',text:t})}
function toast(t){$('toast').className='toast';$('toast').textContent=t;setTimeout(()=>{$('toast').className='';$('toast').textContent=''},2800)}
function sidebar(){return `<div class="brand"><div class="avatar">SH</div><div><strong>Sunday Home</strong><small>Ananya Shah · Owner</small></div></div><div class="navlabel">WORKSPACE</div><button class="nav ${page==='overview'?'active':''}" onclick="goHome()">${icon('home')}<span>Overview</span></button><button class="nav ${page==='case'?'active':''}" onclick="openCase(current)">${icon('spark')}<span>Personal assistant</span></button><div class="navlabel">ENGAGE</div><button class="nav" onclick="goHome()">${icon('chart')}<span>Opportunities</span><span class="count">4</span></button><button class="nav" onclick="modal('studio')">${icon('grid')}<span>Agent Studio</span></button><button class="nav" onclick="modal('connections')">${icon('link')}<span>Connections</span></button><div class="bottom"><div class="panel" style="padding:14px;background:#f0f4fb;box-shadow:none"><div class="row">${icon('shield')}<strong style="font-size:11px">You stay in control</strong></div><p style="font-size:10px;margin-top:8px">Review, edit, approve or stop each intervention.</p></div></div>`}
function goHome(){page='overview';render()}
function openCase(id){current=id;page='case';tab='chat';if(!A().messages.length)bot(C().intro);render()}
function switchTab(t){tab=t;render()}
function heading(title,sub,action=''){return `<div class="heading"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`}
function metric(label,value,sub){return `<div class="panel metric"><div class="label">${label}</div><strong>${value}</strong><small>${sub}</small></div>`}
function overview(){return `<div class="crumb">Workspace / Engage / Opportunities</div>${heading('Campaign outcome studio','Your campaigns, payment signals and next best actions—in one place.',btn(icon('spark')+' Ask your assistant',"openCase('clarity')"))}<section class="hero"><div><div class="eyebrow">Your personal campaign assistant</div><h2>Turn payment signals<br>into better campaign decisions.</h2><p>Explore four opportunities. Ask questions, watch agents work and approve a measured next step—all inside the conversation.</p>${btn('Explore an opportunity '+icon('arrow'),"openCase('clarity')",'primary')}</div><div class="heroart"><div class="floatlabel one">${icon('chart')} A signal worth exploring</div><div class="orb">${icon('spark')}</div><div class="floatlabel two">${icon('shield')} Your approval comes first</div></div></section><div class="metrics">${metric('Opportunities to explore','4','Different problems, different conversations')}${metric('Conversion & retention','3','Clarity, reward cost and repeat timing')}${metric('Revenue recovery','1','Payment incident → safe retry')}${metric('Execution mode','Review first','Fictional scenarios · Simulated actions')}</div><div class="grid"><div><div class="sectionhead"><h2>Choose a situation to explore</h2>${pill('Engage + payment outcomes','blue')}</div><div class="scenario-grid">${Object.entries(CASES).map(([id,c],i)=>`<section class="panel scenario-card"><div class="between">${pill(c.tag,c.color)}<span class="case-number">0${i+1}</span></div><h2>${c.title}</h2><p>${c.pain}</p><div class="case-signal"><strong>${c.signal}</strong><small>${c.impact}</small></div><div class="cardfoot"><span class="fine">${c.short}</span>${btn('Explore '+icon('arrow'),`openCase('${id}')`,'sm primary')}</div></section>`).join('')}</div></div><aside><div class="panel"><div class="row"><div class="agentmini">${icon('spark')}</div><h3>Meet your assistant</h3></div><p class="spaced" style="font-size:12px">It knows the campaign context. It asks for the business decisions only you can make.</p><div class="activity"><span class="point"></span><div><strong>Discuss the opportunity</strong><p>Questions adapt to the selected problem.</p></div></div><div class="activity"><span class="point"></span><div><strong>Watch the work happen</strong><p>Agent steps run inside the chat itself.</p></div></div><div class="activity"><span class="point"></span><div><strong>Approve an exact action</strong><p>Review scope, message, limits and expected outcome.</p></div></div></div><div class="panel sectionspace"><h3>Why four examples?</h3><p class="spaced" style="font-size:12px">Email is one useful channel. Checkout clarity, payment recovery and reward economics show why the experience needs more than a message writer.</p><button class="textbtn spaced" onclick="modal('guide')">How to explore ${icon('arrow')}</button></div></aside></div>`}
function caseView(){let c=C(),a=A();return `<div class="crumb"><button onclick="goHome()">Overview</button> / Engage / ${c.campaign}</div>${heading(c.short, c.channel,`<label class="case-picker">Example <select aria-label="Choose example" onchange="openCase(this.value)">${Object.entries(CASES).map(([id,x])=>`<option value="${id}" ${id===current?'selected':''}>${x.short}</option>`).join('')}</select></label>`)}<div class="tabs case-tabs" role="tablist" aria-label="Opportunity workspace">${[['chat','Personal assistant'],['evidence','Evidence & journey'],['plan','Action plan'],['results','Results'],['activity','Activity']].map(([id,s])=>`<button role="tab" aria-selected="${tab===id}" class="${tab===id?'active':''}" onclick="switchTab('${id}')">${id==='chat'?icon('spark'):''} ${s}${id==='activity'&&a.run?.status==='running'?'<span class="dot"></span>':''}</button>`).join('')}</div>${tab==='chat'?chat():tab==='evidence'?evidence():tab==='plan'?planTab():tab==='results'?resultTab():activityTab()}`}
function context(){let c=C(),a=A();return `<aside class="case-context"><div class="panel"><div class="eyebrow">Current context</div><h3>${c.campaign}</h3><p style="font-size:11px;margin-top:7px">Sunday Home · ${c.tag}</p><div class="contextitem"><span class="fine">SIGNAL</span><strong>${c.signal}</strong><p>${c.impact}</p></div><div class="contextitem"><span class="fine">BUSINESS GOAL</span><strong>${c.metric}</strong></div><div class="contextitem"><span class="fine">STATUS</span><strong id="context-status">${status(a)}</strong><p>All actions shown here are simulated.</p></div><button class="textbtn spaced" onclick="switchTab('evidence')">Open evidence ${icon('arrow')}</button></div><div class="panel sectionspace"><div class="row">${icon('shield')}<h3>Merchant controls</h3></div><p id="permission-status" class="spaced" style="font-size:11px">${a.approved?'Your exact plan is approved. New scope requires a fresh approval.':'The agent can investigate. It needs your approval to act.'}</p><button class="textbtn spaced" onclick="modal('permissions')">Permissions & limits</button></div></aside>`}
function status(a){return a.run&&['running','paused','blocked'].includes(a.run.status)?`Agent ${a.run.status}`:({intro:'Ready to investigate',question:'Waiting for your input',review:'Plan ready for review',done:a.choice==='handoff'?'Draft prepared':'Test scheduled',stopped:'Stopped by merchant',investigating:'Checking signals',executing:'Applying approved plan'}[a.stage]||'Ready')}
function message(m){if(m.role==='receipt')return `<details class="run-receipt"><summary>✓ ${m.type==='investigate'?'Investigation':'Approved execution'} complete · ${m.steps.length} steps</summary>${m.steps.map(x=>`<div class="receipt-step"><span>✓</span><div><strong>${x[0]}</strong> · ${x[2]}</div></div>`).join('')}</details>`;return `<div class="message ${m.role==='user'?'user':''}">${m.role==='bot'?`<div class="agentmini">${icon('spark')}</div>`:''}<div class="messagecontent"><div class="speaker">${m.role==='bot'?'Your campaign assistant':'You'}</div><div class="speech">${safe(m.text)}</div></div></div>`}
function chat(){let a=A();return `<div class="conversationgrid"><section class="panel chatpanel"><div class="chatbar"><div class="row"><div class="agentmini">${icon('spark')}</div><div><h3>Your campaign assistant</h3><small class="fine">Context-aware questions · Scripted prototype</small></div></div><span id="assistant-status" class="pill green">Here to help</span></div><div class="chatscroll" id="chat-scroll"><div class="chat-date">TODAY · ${C().campaign.toUpperCase()}</div>${a.messages.map(message).join('')}<div id="chat-action">${chatAction()}</div></div><div class="chatinput"><div class="suggestions"><button onclick="ask('Why this action?')">Why this action?</button><button onclick="ask('What data do you use?')">What data?</button><button onclick="ask('What can I control?')">My controls</button></div><form onsubmit="sendChat(event)"><input aria-label="Message your personal assistant" placeholder="Ask a question or type your answer…" value="${safe(a.draftInput)}" oninput="A().draftInput=this.value" autocomplete="off"><button class="btn primary" aria-label="Send message">${icon('arrow')}</button></form><small class="fine input-note">Demo recognises the offered choices and questions; no live AI connection.</small></div></section>${context()}</div>`}
function chatAction(){let a=A(),c=C();if(a.stage==='intro')return `<div class="chat-action-card"><p>I’ll check the evidence first. You can pause me at any point.</p>${btn('Investigate this opportunity '+icon('arrow'),"begin('investigate')",'primary spaced')}</div>`;if(['investigating','executing'].includes(a.stage))return runCard();if(a.stage==='question')return `<div class="questionbox"><div class="eyebrow">Your input is needed</div><h3>${c.question}</h3><p>${c.why}</p><div class="choices">${c.choices.map(x=>`<button class="choice" onclick="choose('${x[0]}')"><strong>${x[1]}</strong><small>${x[2]}</small></button>`).join('')}</div><p class="revisit">You can also type your answer below.</p></div>`;if(a.stage==='review')return reviewCard();if(a.stage==='done')return doneCard();return `<div class="chat-action-card"><h3>Work stopped</h3><p>Your messages and evidence are preserved. Unsent work has been cancelled in this demo.</p>${btn('Review again',"A().stage=A().choice?'review':'intro';refreshChat()",'spaced')}</div>`}
function updateMeta(){if($('permission-status'))$('permission-status').textContent=A().approved?'Your exact plan is approved. New scope requires a fresh approval.':'The agent can investigate. It needs your approval to act.';if($('context-status'))$('context-status').textContent=status(A());if($('assistant-status')){$('assistant-status').textContent=A().run?.status==='running'?'Working':A().run?.status==='paused'?'Paused':A().run?.status==='blocked'?'Needs connection':'Here to help';}}
function followChat(){let s=$('chat-scroll'),action=$('chat-action');if(!s)return;if(['review','investigating','executing'].includes(A().stage)&&action){s.scrollTop+=action.getBoundingClientRect().top-s.getBoundingClientRect().top-10}else s.scrollTop=s.scrollHeight}
function refreshChat(){if(page==='case'&&tab==='chat'){const scroll=$('chat-scroll');const html=`<div class="chat-date">TODAY · ${C().campaign.toUpperCase()}</div>${A().messages.map(message).join('')}<div id="chat-action">${chatAction()}</div>`;scroll.innerHTML=html;followChat();paint();}else render()}
function choose(value){let a=A(),c=C();if(a.stage!=='question'){bot('This input is already saved. Use Edit plan to revise it.');refreshChat();return}a.choice=value;user(c.choices.find(x=>x[0]===value)?.[1]||value);if(caseKind()==='repeat')a.cap=value==='60'?600:800;if(caseKind()==='cost'&&Number(value)>425){bot('The proposed ₹75 reward leaves ₹425 before delivery costs, below your requested floor. I cannot recommend this plan. Choose ₹350 or ₹400, or pause for a different cost model.');a.choice=null;refreshChat();return}a.stage='review';bot(value==='handoff'?'Understood. I’ll prepare a reviewable internal draft. There is no permission to publish or contact customers.':`I’ve prepared a bounded plan. Review the exact content and limit below, then approve it here when you’re ready.`);log('Merchant input: '+value);refreshChat()}
function budget(){let a=A();return caseKind()==='cost'?Math.ceil(a.cap/2)*150+Math.floor(a.cap/2)*75:0}
function scopeText(){return A().choice==='handoff'?'Internal draft only · No publication or customer contact':C().scope}
function reviewCard(){let a=A(),c=C();return `<div class="chat-action-card approval-card"><div class="between"><h3>${a.choice==='handoff'?'Prepare an internal brief':c.action}</h3>${pill('Review required','amber')}</div><p class="spaced">${scopeText()}</p><div class="field spaced"><label for="copy">${a.choice==='handoff'?'Draft brief / suggested wording':'Customer-facing content'}</label><textarea id="copy" oninput="edit('copy',this.value)">${safe(a.copy)}</textarea></div><div class="formrow"><div class="field"><label for="limit">${c.capLabel}</label><input id="limit" type="number" min="2" max="${caseKind()==='repeat'&&a.choice==='60'?600:c.max}" value="${a.cap}" oninput="edit('cap',this.value)"></div><div class="field"><label>Maximum incentive budget</label><div class="budget-value" id="budget">₹${budget().toLocaleString('en-IN')}</div></div></div><button class="textbtn" onclick="modal('preview')">Preview what the customer sees ${icon('eye')}</button><div class="fine spaced">${c.terms}</div><div class="approval-preview"><strong>${caseKind()==='cost'?'New variant contribution floor: ₹'+a.choice:'Measurement: 7-day initial read'}</strong><span>${caseKind()==='cost'?'₹425 per retained order before incremental delivery costs':'Refunds and delayed outcomes reviewed before scaling'}</span></div><label class="check"><input id="consent" type="checkbox" onchange="approvalCheck()"><span>I approve this exact plan and its limits.<small>${a.choice==='handoff'?'Prepare the draft only.':'Run once. Further scope changes need my approval.'}</small></span></label><p id="approve-error" class="error" hidden></p><div class="between">${btn('Change my answer',"A().stage='question';refreshChat()",'sm')}${btn(a.choice==='handoff'?'Approve & prepare draft':'Approve & run test',"approvePlan()",'primary')}</div><p class="fine" style="margin-top:10px">Prototype only · No real spending, publication or messages</p></div>`}
function edit(key,value){A()[key]=key==='cap'?Number(value):value;if($('consent'))$('consent').checked=false;if($('budget'))$('budget').textContent='₹'+budget().toLocaleString('en-IN')}
function approvalCheck(){if($('approve-error'))$('approve-error').hidden=true}
function approvePlan(){let a=A(),c=C(),err='';if(!$('consent')?.checked)err='Please review and check the approval box first.';else if(!a.copy.trim())err='Add the content you want the agent to use.';else if(!Number.isInteger(a.cap)||a.cap<2||a.cap>(caseKind()==='repeat'&&a.choice==='60'?600:c.max))err='Choose a whole-number audience within the available limit.';else if(current==='clarity'&&(!/Cedar/i.test(a.copy)||!/credit card/i.test(a.copy)||!/2,?500/.test(a.copy)||!/90/.test(a.copy)||/instant|all cards|any card/i.test(a.copy)))err='Retain Cedar credit card eligibility, the ₹2,500 minimum and 90-day timing. Do not promise instant or all-card cashback.';else if(caseKind()==='cost'&&a.choice!=='handoff'&&!/75/.test(a.copy))err='Keep the approved ₹75 reward in the variant wording.';if(err){$('approve-error').hidden=false;$('approve-error').textContent=err;return}a.approved=true;a.approval={copy:a.copy,cap:a.cap,choice:a.choice,budget:budget()};user(a.choice==='handoff'?'Approved. Prepare this draft only.':'Approved. Run this test within these limits.');begin('execute')}
function stepsFor(type){if(type==='investigate')return C().steps;return [['Policy check','Verify the approved scope','Permission, exact revision and limits checked.'],['Action agent',A().choice==='handoff'?'Prepare an internal brief':'Prepare the approved intervention',A().choice==='handoff'?'Draft saved for merchant review; no sends.':'Campaign variant and customer assignment prepared.'],['Verification agent',A().choice==='handoff'?'Verify the handoff':'Verify schedule and measurement',A().choice==='handoff'?'Handoff is ready. Merchant publication is still required.':'Tracking verified; the test is scheduled in this demo.']]}
function begin(type){let a=A();if(a.run?.status==='running')return;a.stage=type==='investigate'?'investigating':'executing';a.run={type,steps:stepsFor(type),index:0,progress:0,status:'running'};bot(type==='investigate'?'I’m checking the campaign and payment evidence. Here is the work as it happens.':'Your approval is recorded. I’m applying only the plan you reviewed.');log(type==='investigate'?'Read-only investigation requested.':'Exact intervention and limits approved.');refreshChat();lastTick=performance.now();cancelAnimationFrame(raf);raf=requestAnimationFrame(tick)}
function runCard(){let r=A().run;return `<div class="inline-run" id="inline-run"><div class="between"><h3>${r.type==='investigate'?'Investigating your opportunity':'Acting on your approved plan'}</h3><span class="fine" id="run-pct">0%</span></div><div class="progressbar" role="progressbar" id="run-progress" aria-label="Agent progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><div class="progressfill" id="run-fill"></div></div><div class="inline-steps">${r.steps.map((s,i)=>`<div class="inline-step" id="run-step-${i}"><div class="circle" id="circle-${i}"><span id="circle-text-${i}">${i+1}</span></div><div><strong>${s[1]}</strong><p>${s[0]}</p><small id="step-output-${i}"></small></div></div>`).join('')}</div><div id="run-notice" class="run-notice" role="status" hidden></div><div class="runcontrols"><button class="btn sm" id="pause-run" onclick="pauseRun()">Pause</button><button class="btn sm danger" onclick="stopWork()">Stop</button><button class="textbtn" onclick="switchTab('activity')">See activity</button><button id="retry-run" class="btn sm" onclick="retry()" hidden>Reconnect demo source</button></div></div>`}
function tick(t){let dt=Math.min(t-lastTick,100);lastTick=t;let keep=false;for(const [id,a] of Object.entries(sessions)){let r=a.run;if(!r||r.status!=='running')continue;if(!a.connected){r.status='blocked';log('Missing source: paused rather than guessing.',id);if(id===current)paint();continue}r.progress=Math.min(1,r.progress+dt/2100);if(r.progress===1){log(r.steps[r.index][2],id);r.index++;r.progress=0;if(r.index===r.steps.length){r.status='complete';a.stage=r.type==='investigate'?'question':'done';a.messages.push({role:'receipt',type:r.type,steps:r.steps});bot(r.type==='investigate'?CASES[id].finding:a.choice==='handoff'?'The internal draft is ready. Nothing has been sent or published.':'The test is scheduled in this simulated journey. You can pause or cancel it here. I’ll measure paid outcomes, costs and refunds.',id);if(id===current&&page==='case'){if(tab==='chat')refreshChat();else render()}continue}}if(id===current)paint();keep=true}if(keep)raf=requestAnimationFrame(tick)}
function resumeScheduler(){lastTick=performance.now();cancelAnimationFrame(raf);raf=requestAnimationFrame(tick)}

function paint(){let r=A().run;updateMeta();if(!r||!$('run-fill'))return;let p=Math.round((r.index+r.progress)/r.steps.length*100);$('run-fill').style.width=p+'%';$('run-pct').textContent=p+'%';$('run-progress').setAttribute('aria-valuenow',p);r.steps.forEach((s,i)=>{$('run-step-'+i).className='inline-step '+(i<r.index?'complete':i===r.index?'active':'');$('circle-'+i).style.setProperty('--progress',(i<r.index?100:i===r.index?r.progress*100:0)+'%');$('circle-text-'+i).textContent=i<r.index?'✓':i+1;$('step-output-'+i).textContent=i<r.index?s[2]:i===r.index&&r.status==='running'?'Working…':''});$('pause-run').textContent=r.status==='paused'?'Resume':'Pause';$('pause-run').disabled=r.status==='blocked';$('run-notice').hidden=!['paused','blocked'].includes(r.status);$('run-notice').textContent=r.status==='blocked'?'Source unavailable. Reconnect to continue from the last verified step.':'Paused. Your current step is saved.';$('retry-run').hidden=r.status!=='blocked'}
function pauseRun(){let r=A().run;if(!r||!['running','paused'].includes(r.status))return;if(r.status==='running'){r.status='paused';log('Merchant paused the agent.')}else{r.status='running';resumeScheduler();log('Merchant resumed the agent.')}paint()}
function retry(){A().connected=true;A().run.status='running';log('Demo source reconnected.');paint();resumeScheduler()}
function stopWork(){A().results=false;if(A().run)A().run.status='stopped';A().stage='stopped';A().approved=false;log('Merchant stopped work; unsent actions cancelled.');bot('Stopped. I’ve cancelled pending work in this demo. Any message already delivered in a real system could not be recalled.');refreshChat()}
function doneCard(){let a=A();return `<div class="chat-action-card completed-card"><div class="between"><h3>${a.choice==='handoff'?'Your draft is ready':a.paused?'Test paused':'Test scheduled'}</h3>${pill('✓ 3 steps complete','green')}</div><p class="spaced">${a.choice==='handoff'?'Review the brief in Action plan and share it yourself when ready.':`${a.approval.cap} maximum ${C().capLabel.toLowerCase().replace('maximum ','')} · ${scopeText()}`}</p><div class="spaced">${a.choice==='handoff'?btn('Open draft',"switchTab('plan')",'primary'):btn('Preview sample outcome',"showOutcome()",'primary')} ${a.choice!=='handoff'?btn(a.paused?'Resume schedule':'Pause schedule',"toggleSchedule()") : ''}</div><div class="row spaced"><button class="textbtn" onclick="revise()">Edit plan & reapprove</button><button class="textbtn" style="color:#a34d4d" onclick="stopWork()">${a.choice==='handoff'?'Archive draft':'Cancel future sends / exposure'}</button></div>${a.results?`<div class="outcome-chat"><strong>Sample result: ${C().outcome[3]}</strong><p>${C().benefit}</p><button class="textbtn" onclick="switchTab('results')">Review the comparison ${icon('arrow')}</button></div>`:''}</div>`}
function toggleSchedule(){A().paused=!A().paused;log(A().paused?'Merchant paused the unsent schedule.':'Merchant resumed the schedule.');refreshChat()}
function revise(){A().results=false;A().approved=false;A().paused=false;A().stage='review';log('Existing unsent plan cancelled before revision.');bot('I’ve cancelled the pending plan. Make your changes below; the revision will need a new approval.');tab='chat';render()}
function showOutcome(){A().results=true;bot('Here is an illustrative outcome—not a prediction or a live result. I would check uncertainty and later refunds before proposing a wider rollout.');log('Merchant opened illustrative outcome.');refreshChat()}
function sendChat(e){e.preventDefault();let input=e.target.querySelector('input'),t=input.value.trim();if(!t)return;input.value='';A().draftInput='';ask(t)}
function ask(t){let a=A();if(a.stage==='question'){let x=t.toLowerCase();let choice=current==='clarity'?(/agency|handoff/.test(x)?'handoff':/own|landing|card/.test(x)?'owned':null):caseKind()==='recovery'?(/internal|list|no contact/.test(x)?'handoff':/sms|consent|38|opt/.test(x)?'sms':null):caseKind()==='cost'?(x.match(/\b(\d{3,4})\b/)||[])[1]:caseKind()==='repeat'?(/60/.test(x)?'60':/45/.test(x)?'45':null):null;if(choice){choose(choice);return}}user(t);let q=t.toLowerCase();if(/pause/.test(q)&&a.run?.status==='running'){pauseRun();bot('Paused. You can resume the same step below.')}else if(/stop|cancel/.test(q)&&['investigating','executing','done'].includes(a.stage)){stopWork();return}else if(/why|benefit/.test(q)){bot(C().benefit+' '+C().finding)}else if(/data|source|evidence/.test(q)){bot(C().source+' All records here are fictional. The Evidence tab shows the counts and limitations.')}else if(/control|permission|approv/.test(q)){bot(C().guard+' You can edit the proposed content and audience, approve once, pause or stop. No action expands beyond the approved scope.')}else if(/risk|fail|trust/.test(q)){bot('If a required source is missing, I pause. I verify the exact approved revision before any action and check provider status before retrying, to avoid duplicate sends. '+C().guard)}else if(/hello|hi\b/.test(q)){bot('Hi Ananya. I’m here to help with '+C().short.toLowerCase()+'. Start the investigation below, or ask about the data, benefit or controls.')}else if(/model|ai|agent/.test(q)){bot(C().model)}else{bot('This is a scripted prototype, so I can’t reliably interpret that request. Try the choices shown here, or ask “Why this action?”, “What data do you use?”, “What can I control?” or “What happens if it fails?”. I haven’t changed your plan.')}refreshChat()}
function evidence(){let c=C();return `<div class="grid"><div><div class="panel"><div class="eyebrow">Merchant situation</div><h2>${c.title}</h2><p class="spaced" style="font-size:13px">${c.story}</p><div class="callout spaced">${icon('info')}${c.pain}</div><div class="twocol"><div class="comparebox bad"><div class="tagline">Current approach</div><h3>${c.original}</h3><p>${c.finding}</p></div><div class="comparebox good"><div class="tagline">Proposed intervention</div><h3>${c.action}</h3><p>${c.benefit}</p></div></div></div><div class="panel sectionspace"><h3>Follow the merchant journey</h3><div class="journey-map">${['Campaign exposure','Customer action','Payment / reward signal','Merchant decision','Controlled intervention','Paid outcome & costs'].map((s,i)=>`<div><span>${i+1}</span><strong>${s}</strong></div>`).join('')}</div><p class="fine">${c.source}</p></div></div><aside><div class="panel"><h3>Sample evidence</h3>${c.evidence.map(e=>`<div class="ruleline"><span>${e[0]}</span><strong>${e[1]}</strong></div>`).join('')}<p class="fine spaced">Fictional data. Correlation does not establish the cause of a lost purchase.</p></div><div class="panel sectionspace"><h3>What AI adds</h3><p class="spaced" style="font-size:12px">${c.model}</p><button class="textbtn spaced" onclick="showArchitecture()">Behind the scenes ${icon('arrow')}</button></div></aside></div>`}
function customerPreview(){let a=A();return `<div class="phone"><div class="store">SUNDAY HOME</div>${caseKind()==='recovery'?'<div class="preview-channel">SMS · Order reminder</div>':`<div class="productart"><div class="vase"></div><div class="vase second"></div></div>`}<h4>${caseKind()==='cost'?'A reward for your next Sunday':caseKind()==='repeat'?'Make room for your next Sunday':caseKind()==='recovery'?'Your order is waiting':'The Festive Edit'}</h4><div class="shopoffer">${safe(a.copy)}</div><p>${CASES[current].terms}</p><div class="pay">${caseKind()==='recovery'?'View secure order link →':current==='clarity'?'Explore the collection →':'Find your Sunday →'}</div></div>`}
function planTab(){let a=A(),c=C();if(!a.choice)return `<section class="panel empty"><div class="agentmini" style="margin:0 auto 18px">${icon('spark')}</div><h2>A plan starts with your input.</h2><p class="spaced">The assistant will investigate and ask the question that matters for this scenario.</p>${btn('Return to conversation',"switchTab('chat')",'primary spaced')}</section>`;return `<div class="grid"><section class="panel"><div class="between"><h2>${a.choice==='handoff'?'Internal draft':c.action}</h2>${pill(a.approved?'Approved revision':'Draft',a.approved?'green':'amber')}</div><p class="spaced">${scopeText()}</p><div class="comparebox sectionspace"><div class="tagline">${a.choice==='handoff'?'Suggested brief':'Approved / proposed content'}</div><p class="spaced" style="white-space:pre-wrap">${safe(a.copy)}</p></div><div class="ruleline spaced"><span>${c.capLabel}</span><strong>${a.cap}</strong></div><div class="ruleline"><span>Maximum incentive budget</span><strong>₹${budget().toLocaleString('en-IN')}</strong></div><div class="ruleline"><span>Channel / surface</span><strong>${c.channel}</strong></div><p class="fine spaced">${c.terms}</p><div class="nextbar"><p>${a.approved?'Changing the plan cancels pending work and requires approval again.':'Approval happens inside your personal assistant.'}</p>${btn(a.approved?'Edit & reapprove':'Review in chat',a.approved?'revise()':"switchTab('chat')",'primary')}</div></section><aside class="panel"><h3>Customer preview</h3>${customerPreview()}<h3 class="spaced">Execution boundary</h3><p class="spaced" style="font-size:12px">${c.guard}</p><div class="callout amber spaced">${icon('shield')}This cross-product workflow is proposed. Actual API access, channel permissions and connector support need validation with Razorpay.</div></aside></div>`}
function resultTab(){let c=C(),a=A();if(!a.results)return `<section class="panel empty"><h2>${a.choice==='handoff'?'A draft does not produce measured revenue.':'Results follow the approved intervention.'}</h2><p class="spaced">${a.choice==='handoff'?'Publish through an authorised owner before measuring a real outcome.':'Complete the conversation and approval to preview a clearly labelled sample outcome.'}</p>${btn('Return to assistant',"switchTab('chat')",'primary spaced')}</section>`;let cost=caseKind()==='cost',recovery=caseKind()==='recovery';return `<div class="callout">${icon('info')}Illustrative results only. These are sample scenarios, not forecasts or real experiment observations.</div><div class="metrics">${metric('Primary comparison',c.outcome[3],'Test group compared with control')}${metric(c.outcome[0]+' · Control',c.outcome[1],'Original experience / holdout')}${metric(c.outcome[0]+' · Test',c.outcome[2],'Approved intervention')}${metric('Decision','Keep learning','Review uncertainty and mature refunds')}</div><div class="grid"><section class="panel"><h2>What the merchant could gain</h2><p class="spaced">${c.benefit}</p><table class="table sectionspace"><thead><tr><th>Measure</th><th>Control</th><th>Test</th></tr></thead><tbody><tr><td>${c.outcome[0]}</td><td>${c.outcome[1]}</td><td>${c.outcome[2]}</td></tr>${cost?'<tr><td>Purchase conversion</td><td>20%</td><td>18%</td></tr><tr><td>Contribution / retained order</td><td>₹350</td><td>₹425</td></tr>':''}</tbody></table><div class="comparebox good sectionspace"><h3>${cost?'More profit can mean fewer discounted orders.':'A useful signal, with uncertainty.'}</h3><p>${cost?'20% × ₹350 = ₹70 per assigned customer. 18% × ₹425 = ₹76.50. Delivery fees and later refunds must still be accounted for.':recovery?'The contactable cohort is only 38 shoppers: a 19/19 split might show 2 vs 5 paid orders. That is too small to establish reliable incremental lift.':'Compare randomised customer groups, account for campaign delivery and incentive costs, and wait for late refunds before claiming incremental contribution.'}</p></div><details class="sectionspace"><summary>Measurement and attribution notes</summary><p class="spaced" style="font-size:12px">${c.source} Assign treatment before exposure and track all assigned customers, including those who never click. Check delivery balance, repeat exposures, identity-match loss and uncertainty intervals. The rates shown are illustrative and not a power calculation for the selected cap.</p></details></section><aside class="panel"><h3>How the assistant learns</h3><p class="spaced" style="font-size:12px">Record the intervention, merchant edits, assigned groups, paid outcomes and costs. Update recommendations only when the evidence supports them.</p><p class="spaced" style="font-size:12px">Keep the merchant’s data scoped to their business. Cross-merchant learning or model training needs separately validated permissions.</p><button class="textbtn spaced" onclick="switchTab('chat')">Discuss the next step ${icon('arrow')}</button></aside></div>`}
function activityTab(){let a=A();return `<section class="panel"><div class="between"><h2>Agent activity</h2>${pill(status(a),a.run?.status==='running'?'blue':'green')}</div><p class="spaced" style="font-size:12px">A record of this example’s decisions and simulated actions.</p><div class="timeline">${a.logs.length?a.logs.map(l=>`<div class="timelineitem"><strong>${safe(l.text)}</strong><small>${l.t} · ${C().short}</small></div>`).join(''):'<p>No activity yet. Start the investigation in the assistant.</p>'}</div><button class="textbtn" onclick="switchTab('chat')">Return to live conversation ${icon('arrow')}</button></section>`}
function render(){$('sidebar').innerHTML=sidebar();$('main').innerHTML=page==='overview'?overview():caseView();window.scrollTo({top:0,behavior:'instant'});$('journey').innerHTML='';if(page==='case'&&tab==='chat'){paint();followChat()}history.replaceState(null,'',page==='overview'?'#overview':'#'+current+'/'+tab)}
function closeModal(){$('overlay').innerHTML=''}
function modal(type){let c=C(),a=A(),body='',title='';if(type==='preview'){title='Customer preview · '+c.short;body=customerPreview()+'<p>Illustrative presentation. Actual placement and rendering depend on the authorised channel integration.</p>'}else if(type==='guide'){title='Explore four conversations';body='<p>Choose an opportunity. In Personal assistant, start the investigation, answer a context-specific question, edit the plan and approve. The agents investigate and execute inside the same chat.</p><p>Use Evidence & journey to inspect the problem, Action plan to revisit the proposal, Results for sample outcomes and Activity for the record. Each example keeps its own conversation during this session.</p><p>Type a choice or ask about the data, recommendation, controls, risk or AI models. This is a scripted clickable prototype, not a live chatbot. Reloading resets the demo.</p>'}else if(type==='permissions'){title='Your controls and permissions';body=`<p>${c.guard}</p><ul><li>Read scoped campaign, payment and consent evidence.</li><li>Draft freely; act only on a versioned merchant approval.</li><li>Never increase the cap, discount or funding exposure silently.</li><li>Stop unsent work; already delivered messages cannot be recalled.</li><li>Check current status before retrying an uncertain action.</li></ul><p>These are proposed controls. This demo only changes local state.</p>`}else if(type==='connections'){title='Proposed connections';body=`<p>Engage campaign events, offer / reward records, Razorpay payment events and merchant consent / cost records.</p><p>A public, unified API for this entire workflow has not been verified. Meta / Google Ads connectors are not assumed here.</p><div class="ruleline"><span>Current scenario</span><strong>${c.short}</strong></div><div class="ruleline"><span>Demo source status</span><strong>${a.connected?'Connected':'Unavailable'}</strong></div><p>Try disconnecting before an investigation to see the assistant pause safely.</p>${btn(a.connected?'Disconnect demo source':'Reconnect demo source',"A().connected=!A().connected;closeModal();toast('Demo connection updated')",'spaced')}`}else if(type==='studio'){title='One assistant, specialised agent roles';body='<p>The personal bot is the merchant’s point of contact. Behind it, evidence, offer, recovery, incentive and experiment roles use scoped tools for each situation.</p><p>These are logical roles, not necessarily separate models. The proposed Campaign Outcome Agent extends the Agent Studio direction; it is not presented as a verified existing Razorpay agent.</p><p>The tabbed workspace retains the evidence and plan, while the bot asks questions and runs actions in chat.</p>'+btn('See the architecture','closeModal();showArchitecture()','spaced')}else if(type==='sources'){title='References & scope';body=`<div class="sources"><a href="https://razorpay.com/engage/" target="_blank" rel="noopener">Razorpay Engage: offers, rewards and retention channels ↗</a><a href="https://razorpay.com/agent-studio/" target="_blank" rel="noopener">Razorpay Agent Studio ↗</a><a href="https://razorpay.com/docs/payments/offers/create/" target="_blank" rel="noopener">Offer creation and restrictions ↗</a><a href="https://www.nngroup.com/articles/progressive-disclosure/" target="_blank" rel="noopener">Progressive disclosure: details available on demand ↗</a></div><p>The visual foundation is the earlier prototype, with consistent navigation, visible status and reversible merchant decisions. Sunday Home, Cedar Bank and all data are fictional.</p>`}else{title='Behind the scenes';body=`<h3>Signals → interpretation → approval → action → learning</h3><p>${c.model}</p><div class="comparebox spaced"><h3>AI and agents</h3><p>Retrieve scoped evidence, interpret campaign intent and offer terms, explain hypotheses, draft an intervention and coordinate the tools.</p></div><div class="comparebox spaced"><h3>Deterministic safeguards</h3><p>Consent, offer eligibility, paid-status deduplication, contribution calculations, permission checks, caps and idempotency remain fixed checks.</p></div><p>Supported connectors would write only approved changes. Unsupported writes become an internal handoff. No foundation-model training on merchant transactions is required for this concept.</p>`}let dlg=document.createElement('dialog');dlg.className='personal-modal';dlg.setAttribute('aria-label',title);dlg.innerHTML=`<div class="between"><h2>${title}</h2><button class="close" aria-label="Close dialog" onclick="closeModal()">×</button></div>${body}<div class="actions">${btn('Done','closeModal()')}</div>`;$('overlay').replaceChildren(dlg);dlg.showModal()}
function showArchitecture(){modal('architecture')}
function resetDemo(){cancelAnimationFrame(raf);for(const id of Object.keys(sessions))delete sessions[id];page='overview';current='clarity';tab='chat';render()}
render();
